SELECT * FROM domain 
WHERE domain_group = #{domainGroup} 
  AND domain_classification = #{domainClassification} 
  AND name = #{name}

SELECT * FROM domain 
WHERE domain_classification = #{domainClassification}
LIMIT 1

mapper.update:
UPDATE forbidden_word
SET word = #{word},
    replacement = #{replacement},
    description = #{description},
    is_used = #{isUsed}
WHERE id = #{id, jdbcType=OTHER}

mapper.select:
SELECT c.id AS "columnId", c.name AS "columnName", c.data_type AS "columnDataType", t.name AS "tableName", s.name AS "schemaName", ds.name AS "datasourceName", s.id AS "schemaId", ds.id AS "datasourceId" FROM metadata_column c JOIN metadata_table t ON c.table_id = t.id JOIN metadata_schema s ON t.schema_id = s.id JOIN data_source ds ON s.data_source_id = ds.id
ds.id = #{dataSourceId, jdbcType=OTHER}
AND s.id = #{schemaId, jdbcType=OTHER}
ORDER BY ds.name ASC, s.name ASC, t.name ASC, c.name ASC
